"""Generated byte-format controls only; never source recordings or targets."""
import copy
import hashlib
import io
import json
from pathlib import Path
import sys
import unittest
from unittest.mock import patch
import warnings
import zipfile

sys.path.insert(0, str(Path(__file__).resolve().parent))
import numpy as np
import packet
import scorer


def pin(raw):
    return {"bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()}


def encode(doc):
    return (json.dumps(doc, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode()


def archive(values):
    out = io.BytesIO()
    np.savez(out, **values)
    return out.getvalue()


def fixture(arm="neural_wheel_plus_context", phase="query"):
    c = scorer.load_sources()["controls"]
    cases = 10 if phase == "query" else 50
    u = np.arange(cases, dtype=np.float64) / 100
    values = {
        "context.npz": {"u": u, "u_squared": np.square(u)},
        "units.npz": {"unit": np.arange(3, dtype=np.uint32), "source_qc_code": np.array([2, 3, 2], dtype=np.uint8)},
        # Unit2 is intentionally silent; its inventory must remain present.
        "neural.npz": {"trial_index": np.repeat(np.arange(cases, dtype=np.uint32), 2),
                       "unit": np.tile(np.array([0, 1], dtype=np.uint32), cases),
                       "bin_id": np.tile(np.array([0, 4], dtype=np.uint8), cases),
                       "within_bin_seconds": np.full(cases * 2, .005, dtype=np.float64)},
        "wheel.npz": {"trial_index": np.repeat(np.arange(cases, dtype=np.uint32), 10),
                      "bin_id": np.tile(np.repeat(np.arange(5, dtype=np.uint8), 2), cases),
                      "within_bin_seconds": np.tile(np.array([.001, .01], dtype=np.float64), cases * 5),
                      "position_relative_to_first_trial_sample": np.tile(np.arange(10, dtype=np.float64), cases)},
        "labels.npz": {"target": (np.arange(cases) % 3).astype(np.int8)},
    }
    roles = c.parent.roles(arm, phase) if arm in c.ORIGINAL_ARMS else c.roles(arm, phase)
    payloads = {name: archive(values[name]) for name in roles}
    doc = {"schema": "neural093-candidate-public-packet-v1" if arm in c.ORIGINAL_ARMS else c.CONTROL_SCHEMA,
           "candidate_id": "NEURAL-093", "arm": arm, "phase": phase,
           "session_token": hashlib.sha256(b"generated-session").hexdigest(),
           "case_tokens": [hashlib.sha256(f"generated-case-{i}".encode()).hexdigest() for i in range(cases)],
           "case_splits": ["query"] * cases if phase == "query" else ["fit"] * 40 + ["validation"] * 10,
           "query_labels_present": False, "observation": c.parent.OBSERVATION,
           "wheel_observations_present": arm in ("wheel_plus_context", "neural_wheel_plus_context"),
           "files": {name: dict(pin(payloads[name]), role=roles[name]) for name in roles}}
    if arm in c.ORIGINAL_ARMS:
        doc["unit_count"] = 3
    else:
        doc["neural_observations_present"] = False
    return doc, payloads, values


def load(doc, payloads):
    raw = encode(doc)
    return packet.load_packet(raw, pin(raw), payloads, np)


def replace(doc, payloads, name, body):
    payloads[name] = body
    doc["files"][name].update(pin(body))


class PublicPacketControls(unittest.TestCase):
    def test_all_four_query_arms_keep_exact_modalities_and_silent_units(self):
        for arm in scorer.load_sources()["controls"].ARMS:
            doc, payloads, _ = fixture(arm)
            parsed = load(doc, payloads)
            observation = packet.case_observation(parsed, doc["case_tokens"][3], np)
            self.assertEqual("neural" in observation, arm in ("neural_plus_context", "neural_wheel_plus_context"))
            self.assertEqual("wheel" in observation, arm in ("wheel_plus_context", "neural_wheel_plus_context"))
            self.assertNotIn("target", observation)
            self.assertNotIn("source_row", observation)
            self.assertNotIn("session", observation)
            if "units" in observation:
                self.assertEqual(observation["units"]["unit"].tolist(), [0, 1, 2])
                self.assertEqual(observation["neural"]["unit"].tolist(), [0, 1])
                self.assertFalse(observation["neural"]["unit"].flags.writeable)
            self.assertFalse(parsed["whole_panel_authenticated"])

    def test_fitval_labels_and_query_label_exclusion(self):
        doc, payloads, _ = fixture("context", "fitval")
        result = packet.case_observation(load(doc, payloads), doc["case_tokens"][41], np)
        self.assertEqual((result["split"], result["target"]), ("validation", 2))
        doc, payloads, values = fixture("context")
        payloads["labels.npz"] = archive(values["labels.npz"])
        with self.assertRaisesRegex(ValueError, "allowlist"):
            load(doc, payloads)

    def test_all_payload_hashes_before_first_decoder(self):
        doc, payloads, _ = fixture()
        last = next(reversed(payloads))
        payloads[last] = payloads[last][:-1] + bytes([payloads[last][-1] ^ 1])
        with patch.object(packet, "_archive", side_effect=AssertionError("decoded too early")) as decoder:
            with self.assertRaisesRegex(ValueError, "hash"):
                load(doc, payloads)
            decoder.assert_not_called()

    def test_operator_manifest_pin_and_json_keys(self):
        doc, payloads, _ = fixture("context")
        raw = encode(doc)
        with self.assertRaisesRegex(ValueError, "manifest bytes"):
            packet.load_packet(raw, pin(raw + b" "), payloads, np)
        duplicate = b'{"arm":"context",' + raw[1:]
        with self.assertRaisesRegex(ValueError, "duplicate"):
            packet.load_packet(duplicate, pin(duplicate), payloads, np)

    def test_no_current_contrast_or_unregistered_context_fields(self):
        doc, payloads, values = fixture("context")
        values["context.npz"]["current_contrast"] = np.zeros(10)
        replace(doc, payloads, "context.npz", archive(values["context.npz"]))
        with self.assertRaisesRegex(ValueError, "allowlist"):
            load(doc, payloads)

    def test_duplicate_zip_members_and_compression_refused(self):
        doc, payloads, _ = fixture("context")
        for duplicate in (True, False):
            with zipfile.ZipFile(io.BytesIO(payloads["context.npz"])) as original:
                records = [(name, original.read(name)) for name in original.namelist()]
            out = io.BytesIO()
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", UserWarning)
                with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_STORED if duplicate else zipfile.ZIP_DEFLATED) as target:
                    for name, raw in records:
                        target.writestr(name, raw)
                    if duplicate:
                        target.writestr(records[0][0], records[0][1])
            changed, bodies = copy.deepcopy(doc), dict(payloads)
            replace(changed, bodies, "context.npz", out.getvalue())
            with self.assertRaises(ValueError):
                load(changed, bodies)

    def test_object_dtype_rejected_before_array_creation(self):
        doc, payloads, values = fixture("context")
        values["context.npz"]["u"] = np.array([object()] * 10, dtype=object)
        replace(doc, payloads, "context.npz", archive(values["context.npz"]))
        with self.assertRaisesRegex(ValueError, "dtype"):
            load(doc, payloads)

    def test_header_extent_shape_and_nonfinite_context(self):
        buffer = io.BytesIO()
        np.save(buffer, np.array([.1], dtype=np.float64))
        with self.assertRaisesRegex(ValueError, "extent"):
            packet._npy(buffer.getvalue() + b"hidden", "float64", np)
        buffer = io.BytesIO()
        np.save(buffer, np.zeros((1, 1), dtype=np.float64))
        with self.assertRaisesRegex(ValueError, "one-dimensional"):
            packet._npy(buffer.getvalue(), "float64", np)
        doc, payloads, values = fixture("context")
        values["context.npz"]["u"][2] = np.nan
        replace(doc, payloads, "context.npz", archive(values["context.npz"]))
        with self.assertRaisesRegex(ValueError, "context"):
            load(doc, payloads)

    def test_dense_units_qc_and_unknown_event_unit(self):
        for family, field, value in (("units.npz", "unit", 7), ("units.npz", "source_qc_code", 1),
                                     ("neural.npz", "unit", 9)):
            doc, payloads, values = fixture()
            values[family][field][-1] = value
            replace(doc, payloads, family, archive(values[family]))
            with self.assertRaises(ValueError):
                load(doc, payloads)

    def test_native_trial_bin_and_offset_validation(self):
        for field, value in (("trial_index", 10), ("bin_id", 5), ("within_bin_seconds", -.001),
                             ("within_bin_seconds", float("inf"))):
            doc, payloads, values = fixture()
            values["neural.npz"][field][-1] = value
            replace(doc, payloads, "neural.npz", archive(values["neural.npz"]))
            with self.assertRaises(ValueError):
                load(doc, payloads)

    def test_wheel_requires_complete_five_bin_support_and_origin(self):
        for defect in ("missing", "origin"):
            doc, payloads, values = fixture()
            if defect == "missing":
                values["wheel.npz"] = {key: value[:-2] for key, value in values["wheel.npz"].items()}
            else:
                values["wheel.npz"]["position_relative_to_first_trial_sample"][0] = 1
            replace(doc, payloads, "wheel.npz", archive(values["wheel.npz"]))
            with self.assertRaises(ValueError):
                load(doc, payloads)

    def test_native_offsets_preserved_without_invented_nominal_rebinning(self):
        doc, payloads, values = fixture("neural_plus_context")
        edge = np.nextafter(np.float64(.02), np.float64(1))
        values["neural.npz"]["within_bin_seconds"][-1] = edge
        replace(doc, payloads, "neural.npz", archive(values["neural.npz"]))
        parsed = load(doc, payloads)
        observation = packet.case_observation(parsed, doc["case_tokens"][-1], np)
        self.assertEqual(observation["neural"]["within_bin_seconds"][-1], edge)
        self.assertEqual(observation["neural"]["bin_id"][-1], 4)
        self.assertFalse(parsed["source_clock_and_coverage_independently_verified"])


if __name__ == "__main__":
    unittest.main()
